export function hostHeaderValidation(e){return(o,s,t)=>{const r=o.headers.host;if(!r)return void s.status(403).json({jsonrpc:"2.0",error:{code:-32e3,message:"Missing Host header"},id:null});let n;try{n=new URL(`http://${r}`).hostname}catch{return void s.status(403).json({jsonrpc:"2.0",error:{code:-32e3,message:`Invalid Host header: ${r}`},id:null})}e.includes(n)?t():s.status(403).json({jsonrpc:"2.0",error:{code:-32e3,message:`Invalid Host: ${n}`},id:null})}}export function localhostHostValidation(){return hostHeaderValidation(["localhost","127.0.0.1","[::1]"])}